    color_counts = Counter()
    for r in range(rows):
        for c in range(cols):
            color_counts[grid[r][c]] += 1
    background = color_counts.most_common(1)[0][0]

    # Find 8-connected components and their sizes
    visited = [[False]*cols for _ in range(rows)]
    comp_id = [[-1]*cols for _ in range(rows)]
    comp_sizes = []
