        for c in range(cols):
            if not visited[r][c] and grid[r][c] == background:
                continue

            color = grid[r][c]
            size = 0
            q = Queue()
            q.put((r, c))
            visited[r][c] = True
            comp_id[r][c] = next_id

            while not q.empty():
